<div id="vl-chatbot" class="vl-chatbot" data-context="<?= htmlspecialchars($chatbotContextValue, ENT_QUOTES, 'UTF-8') ?>" data-page="<?= htmlspecialchars($chatbotPageContext, ENT_QUOTES, 'UTF-8') ?>">
  <button type="button" class="vl-chatbot-toggle" aria-label="Mở Trợ lý Việt Long"><i class="fa fa-robot"></i><span>Chat</span></button>
  <section class="vl-chatbot-panel" aria-label="Trợ lý Việt Long" hidden>
