    <div class="vl-chatbot-quick"><button type="button" data-question="Nhà sách có những danh mục nào?">📚 Danh mục sách</button><button type="button" data-question="Sách bán chạy">🔥 Bán chạy</button><button type="button" data-question="Sách mới nhất">🆕 Sách mới</button><button type="button" data-question="Sách đang khuyến mãi">🏷️ Khuyến mãi</button><button type="button" data-question="Chính sách giao hàng">🚚 Giao hàng</button><button type="button" data-question="Đơn hàng của tôi">📦 Đơn hàng</button></div>
