<style>
.vl-chatbot{position:fixed;right:20px;bottom:20px;z-index:1050;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.vl-chatbot-toggle{display:flex;align-items:center;gap:8px;border:0;border-radius:999px;padding:12px 16px;background:#f0b90b;color:#20242b;font-weight:800;box-shadow:0 8px 24px rgba(15,23,42,.2);cursor:pointer}.vl-chatbot-toggle i{font-size:18px}.vl-chatbot-panel{width:350px;height:470px;display:flex;flex-direction:column;overflow:hidden;background:#fff;border:1px solid #e2e8f0;border-radius:14px;box-shadow:0 16px 42px rgba(15,23,42,.22)}.vl-chatbot-header{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;background:#20242b;color:#fff}.vl-chatbot-close{border:0;background:none;color:#fff;font-size:24px;line-height:1;cursor:pointer}.vl-chatbot-quick{display:flex;gap:6px;flex-wrap:wrap;padding:9px 10px;background:#fff;border-bottom:1px solid #e2e8f0}.vl-chatbot-quick button{border:1px solid #dbe2ea;border-radius:999px;background:#fff;color:#475569;padding:5px 8px;font-size:11px;cursor:pointer}.vl-chatbot-quick button:hover{background:#eef2ff;color:#4f46e5}.vl-chatbot-actions{display:flex;flex-wrap:wrap;gap:6px;margin:-4px 0 10px}.vl-chatbot-actions button{border:1px solid #c7d2fe;border-radius:999px;background:#eef2ff;color:#3730a3;padding:6px 9px;font-size:11px;cursor:pointer}.vl-chatbot-actions button:hover{background:#e0e7ff}.vl-chatbot-messages{flex:1;overflow-y:auto;padding:14px;background:#f8fafc}.vl-chatbot-message{max-width:88%;margin:0 0 10px;padding:10px 12px;border-radius:11px;white-space:pre-line;font-size:13px;line-height:1.45}.vl-chatbot-message.bot{background:#fff;border:1px solid #e2e8f0;color:#334155}.vl-chatbot-message.user{margin-left:auto;background:#eef2ff;color:#3730a3}.vl-chatbot-message.error{background:#fef2f2;color:#991b1b}.vl-chatbot-form{display:flex;gap:8px;padding:10px;border-top:1px solid #e2e8f0;background:#fff}.vl-chatbot-form input{min-width:0;flex:1;border:1px solid #dbe2ea;border-radius:8px;padding:10px 11px;outline:0}.vl-chatbot-form button{width:42px;border:0;border-radius:8px;background:#4f46e5;color:#fff;cursor:pointer}.vl-chatbot-form button:disabled{opacity:.6}@media(max-width:500px){.vl-chatbot{right:12px;bottom:12px}.vl-chatbot-panel{width:min(350px,calc(100vw - 24px));height:65vh}.vl-chatbot-toggle{padding:11px 13px}.vl-chatbot-toggle span{display:none}}
