.vl-chatbot-quick button{border-color:#a9ccef;background:#ffffff;color:#315b86}
.vl-chatbot-quick button:hover{background:#e5f2ff;border-color:#76afe8;color:#245b92}
.vl-chatbot-messages{background:#f6faff}
.vl-chatbot-message.bot{border-color:#afd1f2;background:#ffffff}
