</style>
<script>
(function(){const root=document.getElementById('vl-chatbot');if(!root)return;const toggle=root.querySelector('.vl-chatbot-toggle'),panel=root.querySelector('.vl-chatbot-panel'),close=root.querySelector('.vl-chatbot-close'),form=root.querySelector('.vl-chatbot-form'),input=form.querySelector('input'),messages=root.querySelector('.vl-chatbot-messages'),quick=root.querySelector('.vl-chatbot-quick');function add(text,type){const el=document.createElement('div');el.className='vl-chatbot-message '+type;el.textContent=text;messages.appendChild(el);messages.scrollTop=messages.scrollHeight;return el}function addButtons(buttons){if(!Array.isArray(buttons)||!buttons.length)return;const wrap=document.createElement('div');wrap.className='vl-chatbot-actions';buttons.forEach(item=>{const button=document.createElement('button');button.type='button';button.textContent=item.label;button.dataset.question=item.question;wrap.appendChild(button)});messages.appendChild(wrap);messages.scrollTop=messages.scrollHeight}toggle.addEventListener('click',()=>{panel.hidden=false;toggle.hidden=true;input.focus()});close.addEventListener('click',()=>{panel.hidden=true;toggle.hidden=false});quick.addEventListener('click',e=>{const button=e.target.closest('button[data-question]');if(!button)return;input.value=button.dataset.question;form.requestSubmit()});form.addEventListener('submit',async function(e){e.preventDefault();const message=input.value.trim();if(!message)return;add(message,'user');input.value='';input.disabled=true;form.querySelector('button').disabled=true;const loading=add('Đang xử lý...','bot');try{const body=new URLSearchParams({message:message,context:root.dataset.context||root.dataset.page||''});const res=await fetch('chatbot_api.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:body});const data=await res.json();loading.remove();add(data.message||'Không thể xử lý câu hỏi lúc này.',data.success?'bot':'error');if(data.success)addButtons(data.buttons)}catch(err){loading.textContent='Không thể kết nối chatbot lúc này.';loading.className='vl-chatbot-message error'}finally{input.disabled=false;form.querySelector('button').disabled=false;input.focus()}})})();
</script>
